// Traduce las acciones que devolvió Postgres a llamadas de la Bot API.
// No hay lógica de negocio aquí: sólo cambio de formato.
const salida = [];

for (const item of $input.all()) {
  const respuesta = item.json.respuesta ?? {};
  const acciones = respuesta.acciones ?? [];

  for (const a of acciones) {
    let metodo;
    let cuerpo;

    if (a.tipo === 'responder_callback') {
      if (!a.callback_query_id) continue;
      metodo = 'answerCallbackQuery';
      cuerpo = { callback_query_id: a.callback_query_id };
      if (a.texto) cuerpo.text = a.texto;
    } else if (a.tipo === 'enviar') {
      metodo = 'sendMessage';
      cuerpo = { chat_id: a.chat_id, text: a.texto, parse_mode: 'HTML' };
    } else if (a.tipo === 'editar') {
      metodo = 'editMessageText';
      cuerpo = {
        chat_id: a.chat_id,
        message_id: a.message_id,
        text: a.texto,
        parse_mode: 'HTML',
      };
    } else {
      continue;
    }

    if (a.botones && a.botones.length > 0) {
      cuerpo.reply_markup = {
        inline_keyboard: a.botones.map((fila) =>
          fila.map((b) => ({ text: b.t, callback_data: b.d })),
        ),
      };
    }

    salida.push({ json: { metodo, cuerpo } });
  }
}

return salida;
